  i = `verta`,
  a = `seksuaalista sisältöä`,
  o = `alastomuutta`,
  s = `ei ehkä sovi kaikenikäisille,`,
  c = `tai ei ehkä sovi töissä katseltavaksi.`,
  l = `Älä varoita minua uudelleen tästä: %1$s`,
  u = `Asetuksesi perusteella sinua varoitetaan mahdollisesti haitallisista kuvista.`,
  d = `Muokkaa asetuksia`,
  f = `Ladataan asetuksiasi`,
  p = `Vaihda tapahtuman kuvitus`,
  m = `Kuvan lataus epäonnistui`,
  h = `Valitse tapahtuman tai ilmoituksen pääteema. Valitsemasi kategorian tulee olla tapahtuman nimen, kuvituksen ja kansikuvan mukainen.`,
  g = `Mitä tapahtumasi tai ilmoituksesi koskee?`,
  _ = `Vaihda kategoriaa`,
  v = `Luokka`,
  y = `Et voi muuttaa tapahtuman kategoriaa, jos sen päivityssivu on käytössä. Ota päivityssivu ensin pois käytöstä Aloitussivu-välilehdeltä.`,
  b = `Et voi muuttaa kehittäjän kotisivun luokitusta.`,
  x = `Et voi muuttaa markkinointiviestiin sidotun ison päivityksen luokitusta.`,
  S = `Pelipäivitys`,
  C = `Kerro pelaajille isoista tai pienistä päivityksistä, uudesta sisällöstä, toimintojen muutoksista tai bugikorjauksista.`,
  w = `Kutsu fanisi juttelemaan, tapaamaan kehittäjiä ja esittämään kysymyksiä.`,
  T = `Kerro käyttäjille, että pelisi on nyt saatavilla.`,
  E = `Kannusta käyttäjiä katsomaan peliäsi, kuten turnausta, kehittäjän suoratoistoa tai kuuluisaa striimaajaa.`,
  D = `Paras vaihtoehto korjauksiin ja pieniin muutoksiin, jotka vaikuttavat vain osaan pelaajista.`,
  O = `Paras vaihtoehto säännöllisille, esimerkiksi kerran viikossa tai kerran kuussa ilmestyville päivityksille.`,
  k = `Säästä nämä isoimmille päivityksillesi, jotka tapahtuvat tyypillisesti kerran vuosineljänneksessä tai muutaman kerran vuodessa.`,
  A = `Ilmoita pelisi uudesta ostettavasta lisämateriaalista.`,
  j = `Ilmoita pelaajille tarkasta julkaisuajankohdasta.`,
  M = `Ilmoita määräaikaisesta alennuksesta tässä pelissä.`,
  N = `Ilmoita alennuksista tuotteista, jotka saattaisivat kiinnostaa nykyisiä pelaajia, kuten virtuaaliesineet, virtuaalivaluutat tai lisämateriaalit.`,
  P = `Ilmoita ajankohdasta, jolloin käyttäjät saavat pelisi pelaamisesta lisäpisteitä.`,
  F = `Ilmoita uuden, harvinaisen tai ainutlaatuisen saaliin löytömahdollisuudesta. Osallista pelaajia ja paranna saaliin saantimahdollisuuksia.`,
  I = `Ilmoita pelaajille, että heillä on rajoitetun ajan mahdollisuus saada bonuksia ja etuja suorittamalla tehtäviä tai osallistumalla yhteisötapahtumiin.`,
  L = `Päivittäinen, viikottainen, kuukausittainen tai erityishaaste.`,
  R = `Pyydä faneja tekemään vaikka kuvitusta tai Workshop-luomus osallistuakseen kilpailuun. Tai he voivat osallistua kilpailulliseen moninpeliin.`,
  z = `Kutsu fanit tapaamaan kasvotusten. Ilmoita, jos olet menossa kiinnostavaan paikkaan.`,
  B = `Kerro pelaajille joku uutinen tai tarina. Saavutitko jonkin virstanpylvään? Työstätkö jotain mielenkiintoista?`,
  V = `Ajoita beta tai kerro betaan osallistumisen lisätiedoista.`,
  H = `Rajoitetun ajan voimassa oleva ilmaistarjous Steamin asiakkaille, jotta he voivat kokeilla peliäsi, lisämateriaalia tai pelinsisäistä materiaalia. Kyse voi olla ilmaisviikonlopusta, pelidemosta tai muusta rajoitetun ajan voimassa olevasta tarjouksesta.`,
  U = `Kerro uuden kausi- tai taistelupassin julkaisusta. Kausi kestää yleensä joitain viikkoja tai kuukausia ja käsittää ylimääräistä sisältöä, etuja tai tapahtumia.`,
  W = `Käytä tätä luokkaa, jos haluat kertoa toisesta pelistä, jonka olet julkaisemassa, tai toisesta alustasta, jolle pelisi on tulossa. Tämä on ainoa luokka, jota sinun tulisi käyttää, jos julkaisusi koskee eri peliä, alustaa tai kauppaa.`,
  G = `Kannusta yleisöäsi pelaamaan peliäsi tiettyyn aikaan yhdessä.`,
  K = `Järjestä rajatun ajan halloween-teemainen pelitapahtuma.`,
  q = `Muokkaa kehittäjän kotisivua (kehittäjän, julkaisijan tai pelisarjan sivua). Tuorein julkinen versio näytetään asiakkaille.`,
  J = `Ilmoita pelisi uusista virtuaaliesineistä tai sisällöstä.`,
  Y = `Lisätietoja aiemmasta kaudesta tai taistelupassista. Päivitetty sisältö kannattaa aikatauluttaa jaksoihin.`,
  X = `Peli- tai sisältöjulkaisu / betatestaus`,
  Z = `Ilmoita pelisi, betan, lisämateriaalin tai erikoiskauden julkaisuajankohdasta.`,
  Q = `Kuvaile uuden lisämateriaalin, kauden tai taistelupassin julkaisu. Kerro asiakkaille, minkälaista sisältöä on tarjolla ja joutuuko siitä maksamaan erikseen.`,
  ne = `Striimaustapahtuma voi olla Steam-lähetys tai ulkoinen striimaussivusto. Voit määrittää alkamis- ja päättymisajat. Steam-lähetykset voivat näkyä kauppasivulla tai Steam-kotisivulla.`,
  re = `Valitse livelähetystyyppi`,
  ie = `Alennus, kampanja tai ilmainen kokeilu`,
  ae = `Pelisi, lisämateriaalien tai pelisisällön alennuksille, kokeilujaksoille, demoille ja tarjouksille. Ilmoita pelitarjouksesta niille, joilla peliä ei ole tai tiedota nykyisille pelaajille pelinsisäisestä tarjouksesta.`,
  oe = `Alennukset piilotetaan yleensä niiden alkamisaikaan asti. Täällä voit aikatauluttaa alennuskampanjan sekä siihen liittyvät ilmoitukset ja kuvituksen.`,
  se = `Valitse alennustyyppi`,
  ce = `Aikatauluta pelin tai lisämateriaalin alennus, jotta se näkyy Steamin kaupassa.`,
  le = `Pelinsisäinen tapahtuma`,
  ue = `Ilmoita ajanjaksosta, jolloin pelaajat voivat osallistua pelissä oleviin tapahtumiin ansaitakseen palkintoja tai vain viettääkseen aikaa yhdessä.`,
  de = `Lisäetuja, palkintoja tai bonuksia`,
  fe = `Kannusta yleisöäsi pelaamaan erityispalkinnoilla tai bonuksilla.`,
  pe = `Ilmoita pelisi rajoitetun ajan voimassa olevista tapahtumista, jolloin pelaajat saavat lisäesineitä, bonuksia, etuja, palkintoja, kokemuspisteitä ja muuta. Tapahtumilla on aloitus- ja päättymisaika.`,
  me = `Valitse tapahtumatyyppi`,
