  ge = `Haasta pelaajat suorittamaan tiettyjä tehtäviä tai osallistumaan kilpailuun.`,
  _e = `Ilmoita asiakkaille pelisi rajoitetun ajan voimassa olevasta haasteesta.`,
  ve = `Valitse haastetyyppi`,
  ye = `Pelin %1$s erikoistapahtumat`,
  be = `Tämän tapahtumatyypin avulla pelisi nousee tapahtumassa erityisesti esille. Klikkaa infopainiketta alla saadaksesi lisätietoja käyttötavoista tapahtuman %1$s aikana.`,
  xe = `Lisätietoja tapahtumatyypeistä`,
