  Ce = `Voit luoda enintään %1$s tämäntyyppistä tapahtumaa.`,
  we = `Olet jo luonut %1$s.`,
  Te = `Muuta`,
  Ee = `Jokin erityinen tapahtuma tai viesti.`,
  De = `Pelipäivitys – Useimmiten peliin päivitetään uutta sisältöä ja muutoksia automaattisesti`,
  Oe = `Iso päivitys – Ilmoitus pelin tai sen lisämateriaalin julkaisusta`,
  ke = `Lähetys – Pelillä on kehittäjän järjestämä, virallinen livestriimaus`,
  Ae = `Ale – Peli ja/tai sen lisämateriaali ovat alessa!`,
  je = `Pelinaikainen tapahtuma – Käynnissä on jännittävä pelinaikainen tapahtuma, johon osallistumalla voi saada erityistehtäviä, etuja tai bonuksia`,
  Me = `Chat – kehittäjä järjestää keskustelun, jossa kehitystiimin jäsenet voivat kertoa asioista ja vastata kysymyksiin.`,
  Ne = `IRL – Kehittäjä järjestää tapahtuman, jossa hänet voit tavata.`,
  Pe = `Uutiset – peliyhteisölle ilmoitetaan jostain uutiskynnyksen ylittävästä.`,
  Fe = `Muuta – Tapahtuma ei sovi Steamin määrittelemään kategoriaan, eikä sitä ole sen vuoksi luokiteltu.`,
  Ie = `Tämä osio tarjoaa tietoa, miten tämä tapahtuma poikkeaa normaalista, kun pidät hiiren kursoria tietyn kategorian yläpuolella`,
  Le = `Pidä hiirtä tapahtumaluokan yläpuolella, jotta voit nähdä yhteenvedon.`,
  Re = `%1$s näytetään kaikissa tutuissa paikoissa, mukaan luettuna kirjasto, kauppasivu ja yhteisökeskus.`,
  ze = `%1$s näytetään kaikissa tutuissa paikoissa seuraavin poikkeuksin:`,
  Be = `Lisätietoa näkyvyydestä`,
  Ve = `Nämä viestit eivät näy kirjaston kotisivulla.`,
  He = `Nämä julkaisut näytetään vain kaikkein sitoutuneimmille faneille Steam-yhteisössä ja seuraajien tapahtumasyötteessä.`,
  Ue = `Nämä julkaisut ovat olennaisimpia mahdollisille asiakkaille, joten näitä julkaisuja ei näytetä Steam-kirjaston koti- tai tietosivulla.`,
  We = `Nämä julkaisut eivät näy Steam-kirjaston kotisivulla.`,
  Ge = `Nämä julkaisut eivät näy Steam-kirjaston kotisivulla.`,
  Ke = `Nämä julkaisut eivät näy Steam-kirjaston kotisivulla.`,
  qe = `Lisätietoja`,
  Je = `Kansikuvaa ei vaadita.`,
  Ye = `Suosittelemme, että luot tapahtumaa varten valokeilakuvan pelin tietosivulle kirjastossa.`,
  Xe = `Vaatii sekä aloitus- että päättymispäivän.`,
  Ze = `Tapahtuma-ajat voiva olla vain aikavälillä: %1$s ja %2$s`,
  Qe = `Tapahtuma-aikojen pitää olla ennen %1$s`,
  $e = `Tapahtuma-aikojen pitää olla %1$s jälkeen`,
  et = `UUTTA: ehdotukset Steam-palkintojen saajiksi`,
  tt = `Kutsu fanisi nimeämään pelisi tämän vuoden Steam-palkintoehdokkaaksi. (Kategoria on saatavilla vain nimeämisen päättymiseen saakka.)`,
  nt = `Nämä julkaisut eivät näy Steam-kirjaston kotisivulla.`,
  rt = `UUTTA: Pyyntö äänestää Steam-palkintoja`,
  it = `Kutsu fanisi äänestämään peliäsi tämän vuoden Steam-palkinnon saajaksi. (Kategoria on saatavilla vain talvialen loppuun saakka.)`,
  at = `- Nämä viestit eivät näy Steam-kirjaston kotisivulla`,
  ot = `+ Nämä viestit tuovat pelille enemmän näkyvyyttä Steam-palkintojen nimeämissivulla`,
  st = `+ Nämä viestit merkitään oletusarvoisesti esiteltäviksi, ja ne kiinnitetään kirjastosivun yläosaan`,
  ct = `Steam Next Fest: erikoistapahtumat`,
  lt = `Lisätietoa Steam Next Festistä`,
  ut = `Valinnainen: voit luoda jopa kaksi seuraavanlaista tapahtumatyyppiä Steam Next Festin aikana.`,
  dt = `Julkaistulle tapahtumalle ei voi valita tätä tyyppiä. Sen voi valita vain uusille tapahtumille.`,
  ft = `Valvelaisena voit ohittaa tämän. Julkaistun tapahtuman muuttamista ei lasketa sallittuun enimmäismäärän, joten tee muutos harkiten.`,
  pt = `Voi julkaista vain %1$s tämäntyyppisen tapahtuman. Raja on jo saavutettu.`,
  mt = `Voit julkaista vain %1$s tämäntyyppistä tapahtumaa. Raja on jo saavutettu.`,
  ht = `Ota yhteyttä kehittäjätukeen`,
  gt = `Valvelaisena voit ohittaa rajan, määrittää asetukset ja julkaista tapahtuman heidän puolestaan.`,
  _t = `Steam Next Fest: pikaesittely`,
  vt = `Käytä tätä osiota kertoaksesi asiakkaille kehitystiimistä, demon sisällöstä ja siitä, miten se liittyy peliin. Valinnainen kuvaus näkyy pelisi Steam-kauppasivulla sekä Next Fest -sivuilla.`,
  yt = `Steam Next Fest: suoratoisto`,
  bt = `Valitse aika ja ilmoita faneille, että olet paikalla ja lähetät silloin peliä livenä. Tapahtuma näkyy Steam Next Festin virallisessa kalenterissa ja automaattisesti pelin sivulla.`,
  xt = `Steam Next Fest -infotilaisuus`,
  St = `Valitse aika, jolloin fanit voivat olla yhteyksissä sinuun ja tiimiin, esittää kysymyksiä ja chattailla kanssasi. Voit järjestää tapaamisen siellä, missä mieluiten chattailet ja vastailet kysymyksiin. Olkoon se sitten Steam-chat, Discord, Redditin AMA tai jokin muu.`,
  Ct = `Ryhmäilmoitus`,
  wt = `Uutisia vain ryhmän jäsenille`,
  Tt = `Nämä ilmoitukset näkyvät ainoastaan ryhmän etusivulla`,
  Et = `Julkinen uutinen`,
  Dt = `Uutisia ryhmän jäsenille sekä käyttäjille, jotka seuraavat tätä kuraattoria`,
  Ot = `Aletapahtuma`,
  kt = `Luo kehittäjän kotisivusi peleille alen aloitussivu.`,
  At = `Nämä julkaisut näkyvät ryhmän etusivulla ja seuraajiesi henkilökohtaisissa uutiskeskuksissa.`,
  jt = `Näyttökerrat: %1$s, lukukerrat: %2$s`,
  Mt = `Näyttökerrat: %1$s`,
  Nt = `Lukukerrat: %1$s`,
  Pt = `Tapahtuma-aikataulun widget mahdollistaa tulevien tapahtumien selaimen upottamisen tarjoussivulle ja antaa esitellyille peleille lisänäkyvyyttä. Lisäksi se palkitsee vuorovaikutuksen Steam-yleisön kanssa pelikohtaisilla tapahtumilla alen aikana. Esimerkiksi suoratoistot ja chatit ovat hyvä keino olla vuorovaikutuksessa Steamin käyttäjien kanssa.`,
  Ft = `Valitse vähintään yksi tapahtumatyyppi, joka näytetään aikataulussa.`,
  It = `Määritä aikataulun ajanjakso. Se voi olla sama kuin tapahtuman aikataulu tai eri, jos kyseessä on ilmoitus tulevasta tapahtumasta.`,
  Lt = `Tarjoussivulla on oletuksena %1$s, josta tapahtumat löytyvät. Se näkyy heti alen ylläpitäjille ja kaikille, kun tarjoussivu on julkinen.`,
  Rt = `Uutiskeskus`,
  zt = `%1$s tapahtumatyyppi käytössä`,
  Bt = `%1$s tapahtumatyyppiä käytössä`,
  Vt = `Demojen esittely widgetissä`,
  Ht = `Kun tämä on valittuna, demon toistaminen menee edelle, kun näytetään pelitietoja tai valitaan hiirellä osoittamalla. Lisäksi käynnistyy demon julkaisutapahtuma aikataulutetulla aikavälillä.`,
  Ut = `Määritä tapahtuman alkamisaikaan`,
  Wt = `Määritä tapahtuman päättymisaikaan`,
  Gt = `Mukana olevat tapahtumat:`,
  Kt = `Näytä aikataulussa kaikki esiteltäviin sovelluksiin liittyvät tapahtumat`,
  qt = `Aikataulussa luetellaan aina kaikki perusryhmään liittyvät tapahtumat ja kaikki sarjan tapahtumat. Valintaruudun rastitus näyttää aikataulussa sekä esiteltävät sovellukset että niihin liittyvät tapahtumat. Rastin poistaminen näyttää vain isännöivän yhteisöryhmän tapahtumat tai sarjoissa erikseen luetellut tapahtumat.`,
  Jt = `Varoitus: Aloitusaika on määritetty ennen tapahtuman aloitusaikaa. Onko tämä varmasti oikein?`,
  Yt = `Oletko varma?`,
  Xt = `Varmastiko? Menetät kaikki tallentamattomat muutokset.`,
  Zt = `Tapahtumaeditori`,
  Qt = `Muokkaa tapahtumaa`,
  $t = `Muokkaa sivua`,
