  rn = `Julkaisematon`,
  an = `Piilotettu`,
  on = `Näkyy julkisesti`,
  sn = `Steamin käyttäjät näkevät tapahtuman, mitä ei voi perua. Jos tapahtuma halutaan piilottaa, se on poistettava.`,
  cn = `Listaamaton ja näkyvissä`,
  ln = `Tapahtuma näkyy niille Steam-käyttäjille, jotka klikkaavat sivulle vievää linkkiä. Tapahtuman näkyvyysasetusta ei voi muuttaa, ja ainoa tapa piilottaa tapahtumasivu on poistaa se kokonaan.`,
  un = `Kirjaston näkyvyys odottaa moderointia`,
  dn = `Piilotettu %1$s asti`,
  fn = `Vaiheistettu ja piilotettu tapahtuman alkuun %1$s saakka`,
  pn = `Tapahtuma on julkaistu mutta piilotettu määritettyyn ajankohtaan asti. Lisätoimenpiteitä ei edellytetä. Tapahtuma julkaistaan Steamin asiakkaille kyseisenä aikana automaattisesti.`,
  mn = `Tapahtuma on automaattisesti julkinen sen alkaessa.`,
  hn = `Tapahtuma on julkinen ennen sen alkamista: %1$s`,
  gn = `Tapahtumat järjestetään tulevaisuudessa mutteivät ole julkisia ennen alkamisajankohtaa. Lisätoimenpiteitä ei edellytetä. `,
  _n = `Piilotettu, julkaisematon`,
  vn = `Tapahtuma on luonnostilassa. Ainoastaan yhteisön jäsenet voivat nähdä sen. Kaikki muutokset ovat piilotettuja, kunnes julkaiset tapahtuman.`,
  yn = `RSS-syötteen julkaisema. Klikkaa avataksesi RSS-ylläpitäjä.`,
  bn = `Alesivu`,
  xn = `URL-osoite, kun tapahtuma näkyy julkisesti:`,
  Sn = `Kieli`,
  Cn = `Valitse kieli alasvetovalikosta, jotta voit nähdä ja muokata tekstikenttiä tietylle kielelle. Voit myös käyttää vie/tuo-vaihtoehtoa, jolla voit lisätä useamman kielen kerralla.`,
  wn = `Ei valittua kieltä`,
  Tn = `Kauppasivulle täytyy määrittää mukautettu URL-osoite ennen alesivun julkaisua. Tätä osoitetta käytetään URL-osoitteena, josta asiakkaat pääsevät alesivulle.`,
  En = `Tapahtuman päivityssivun mukautettu URL-osoite on määritettävä ennen alesivun julkaisua. Tätä osoitetta käytetään URL-osoitteena, josta asiakkaat pääsevät alesivulle.`,
  Dn = `Esikatsele alea`,
