  Nn = `Muokkaa tapahtumaa`,
  Pn = `Tunnistekuvat`,
  Fn = `Brändää tapahtuma tai ilmoitus yläreunan isolla kuvalla`,
  In = `Vedä kuvia alhaalta tai lataa valitsimen kautta uusia kuvia`,
  Ln = `1 920 x 620 pikseliä`,
  Rn = `Valitse kuva`,
  zn = `Tapahtuman otsikko`,
  Bn = `(Enimmäismerkkimäärä %1$s täynnä.)`,
  Vn = `Ilmoituksen otsikko`,
  Hn = `Sisäinen otsikko`,
  Un = `Tapahtuman lisätiedot`,
  Wn = `Lisätiedot`,
  Gn = `Kuvaus`,
  Kn = `Näkyvyys`,
  qn = `Osion otsikko`,
  Jn = `Tee valinta osion yläreunassa näkyvästä ennalta käännettyjen vaihtoehtojen listasta. Voit myös antaa oman nimesi klikkaamalla kohtaa Räätälöity nimi. Kirjoita tekstikenttään löytääksesi ennakkoon käännetyn nimen.`,
  Yn = `Alaotsikko`,
  Xn = `(Enintään %1$s merkkiä. Näytetään tapahtuma- tai ilmoitussivun yläosassa.)`,
  Zn = `(Enimmäismerkkimäärä %1$s täynnä. Näytetään tapahtuma- tai ilmoitussivun yläosassa.)`,
  Qn = `Kehittäjän kotisivun kakkosversion sivut ovat joustava tapa räätälöidä julkaisijan, kehittäjän tai pelisarjan sivua.`,
  $n = `Sivu ei ole näkyvissä. Julkaise sivu, jotta voit tehdä siitä kehittäjän kotisivun.`,
  er = `Sivu <1>ei ole</1> tällä hetkellä käytössä oleva kehittäjän kotisivu. Aktivoi sivu <2>kehittäjän kotisivun työpöydällä</2>.`,
  tr = `Tämä sivu on nykyinen kehittäjän kotisivusi. Asetusta voi hallinnoida <1>kehittäjän kotisivun työpöydällä</1>.`,
  nr = `Avatar`,
  rr = `Muokkaa <1>kehittäjän kotisivun editorissa</1>`,
  ir = `Tunnuslause`,
  ar = `Muokkaa <1>kehittäjän kotisivun työpöydällä</1>`,
  or = `Tervetuloa!`,
  sr = `<1>Omat pelit</1> – Pelisi näkyvät alla olevassa linkitettyjen sovellusten listassa ja ovat valmiina käytettäväksi. Lisäämällä ja määrittämällä osioita alla voit markkinoida pelejä, lisämateriaaleja, demoja ja ääniraitoja tarpeisiisi parhaiten sopivalla tavalla.`,
  cr = `<1>Puuttuvien pelien linkittäminen</1> – Jos alta olevasta listasta puuttuu pelejä, et ole vielä linkittänyt niitä tälle kehittäjän kotisivulle. Ohjeet pelin linkittämiseen kotisivulle löytyvät <2>Kehittäjien ja julkaisijoiden kotisivut</2> -dokumentaatiosta.`,
  lr = `<1>Oletusmääritykset</1> – Alla olevat oletusosiot on jo määritetty korostamaan suosittuja, suositeltuja ja viimeisimpiä julkaisuja. Voit käyttää juuri niin montaa (tai harvaa) oletusosiota kuin haluat.`,
  ur = `Lue lisää aihetta koskevasta dokumentaatiosta.`,
  dr = `Luokka: %1$s`,
  fr = `Tapahtuman kopiointivirhe`,
  pr = `Tapahtuman kloonausprosessin valmistelussa esiintyi virhe: %1$s`,
  mr = `Tapahtuman julkaisuvirhe`,
  hr = `Tapahtuman julkaisuvalmisteluprosessin aikana tapahtui virhe: %1$s`,
  gr = `Ale sisältää laajan linkitettyjen tuotteiden listan, joten sen tuotetunnisteita luodaan uudelleen kaupasta. Tämä voi kestää hetken.`,
  _r = `Emme voineet luoda uudelleen alen tuotetunnisteita kaupasta, joten editoria ei voi avata turvallisesti. Lataa sivu uudelleen.`,
  vr = `%1$s linkitettyjen tuotteiden listalla olevaa tuotetta ei voitu ladata kaupasta, todennäköisesti siksi, että ne on kielletty tai ne eivät enää ole myynnissä. Kyseisten tuotteiden tunnisteita ei luotu uudelleen, joten ne saattavat puuttua tunnisteiden perusteella suodatetuista osioista. (Voit jatkaa normaalisti, jos tuotteet on kielletty jne.): %2$s. `,
  yr = `Tapahtuman alkamispäivä`,
  br = `Ilmoituspäivä`,
  xr = `Nyt – Kun tapahtuma on julkaistu`,
