  Tr = `Suunniteltu alkamispäivä`,
  Er = `Suunniteltu julkaisupäivä`,
  Dr = `Voit tehdä tapahtumasta julkisen ennen alkamispäivää, jos haluat kertoa siitä ja ilmoitusten tilaamisesta pelaajille.`,
  Or = `Voit tehdä ilmoituksesta julkisen ennen alkamispäivää, jos haluat kertoa tapahtumasta ja ilmoitusten tilaamisesta pelaajille.`,
  kr = `Tapahtuman päättymispäivä`,
  Ar = `Tämän luokan tapahtumilla on yleensä päättymispäivä.`,
  jr = `Valitse päättymispäivä, että Steam osaa näyttää, kun tapahtuma on päättynyt. Tämä mahdollistaa Steamin priorisoimaan muut tapahtumasi, jotka ovat tuoreempia tai parhaillaan aktiivisia.`,
  Mr = `Päättyy, kun alkamispäivästä on kulunut tietty aika.`,
  Nr = `Päättymisajaksi pyöristetään %1$s`,
  Pr = `Päättymispäivä`,
  Fr = `Editorin tapahtuma-ajat näytetään paikallisessa ajassa ja Steamin asiakkaille heidän ajassaan.`,
  Ir = `Päättyy määritettynä aikana...`,
  Lr = `Syötä ajat oman aikavyöhykkeesi aikoina. Ne muutetaan automaattisesti pelaajien paikallisajaksi.`,
  Rr = `Automaattiset muistutukset`,
  zr = `Jos määrität tapahtuman alkamaan tulevaisuudessa JA laitat sen näkyviin faneillesi aiemmin, heidän on mahdollista ottaa tapahtuman alkaessa lähetettävät muistutukset käyttöön. Käyttäjän asetuksista riippuen Steam lähettää automaattisesti push-ilmoituksen ja/tai sähköpostin Steam-käyttäjälle.`,
  Br = `Tämä testi lähetetään vain sinun tilillesi, jos olet vahvistanut sähköpostiosoitteesi ja/tai sinulla on asennettuna %1$s.`,
  Vr = `Steam-mobiilisovellus`,
  Hr = `Tapahtumailmoituksen testi`,
  Ur = `* Toiminto on pois päältä, koska tapahtumaa ei ole määritetty tulevaisuuteen.`,
  Wr = `Liittyvä sovellustunnus (AppID)`,
  Gr = `Liitä sovellustunnus (AppID) tähän tapahtumaan?`,
  Kr = `Mahdollistaa sovellustunnuksen (AppID) liittämisen tapahtumaan. Tämä nostaa kaupan tunnistekuvan automaattisesti esille näytettävän tapahtuman kuvauksen alaosassa ja toimittaa sovellustiedot tarvittaessa muille widgeteille, kuten lähetys- tai aikatauluwidgeteille.`,
  qr = `Alkaa`,
  Jr = `Päättyy`,
