  $r = `Ilmoituksen sisältö`,
  ei = `Käytä visuaalista editoria`,
  ti = `Linkki koontiversioon`,
  ni = `Liitä julkaisuun pelin koontiversio, niin tämä viesti näkyy päivitystiedoissa Steamin Lataukset-ikkunassa.`,
  ri = `Tapahtumaa ei ole linkitetty mihinkään koontiversioon.`,
  ii = `Tapahtuma on linkitetty koontiversioon %1$s.`,
  ai = `Tapahtuma on linkitetty koontiversioon %1$s haaran %2$s osalta.`,
  oi = `Valitse haara`,
  si = `Valitse haara, jonka haluat liittää tapahtumaan. Näin haara liitetään tapahtumaan sen tämänhetkisellä koontiversiolla. Voit myös poistaa koontiversion linkityksen tapahtumaan valitsemalla Älä yhdistä tapahtumaan koontiversiota.`,
  ci = `Oletushaara – koontiversio %1$s (%2$s)`,
  li = `%1$s – koontiversio %2$s (%3$s)`,
