  fi = `Palauta tapahtuma tähän versioon`,
  pi = `Haluatko varmasti palauttaa tapahtuman valittuun versioon? Kaikki tallentamattomat muutokset hylätään ja tapahtuman aiempi tila palautetaan.`,
  mi = `Muokannut: %1$s`,
  hi = `Palautetaan tapahtuma edelliseen versioon`,
  gi = `Palauttamisessa tapahtui virhe. Yritä myöhemmin uudelleen.`,
  _i = `Palautus`,
  vi = `Tapahtumahistoria (viimeiset 100 merkintää)`,
  yi = `Alla on listaus uusimmista tapahtumaan tehdyistä muutoksista. Voit valita palautettavan version, jos haluat perua muutokset.`,
  bi = `Vertaa edelliseen`,
  xi = `Vertaa nykyiseen`,
