  Oi = `Kirjoita tapahtumakuvaus tähän`,
  ki = `Syötä osion teksti tähän`,
  Ai = `Liittyy suoratoistoon`,
  ji = `Jos Steamin asiakas piilottaa tiliasetuksistaan kaupan suoratoistot, tämä osio piilotetaan myös, koska sen renderöinti liittyy suoratoistettuun sisältöön.`,
  Mi = `Piilota, jos suoratoisto on pois päältä`,
  Ni = `Näkyvyys`,
  Pi = `Jos katselija ei ole kirjautuneena sisään, estä tämän osion näkyminen sivulla.`,
