  Vi = `Valitse kuva`,
  Hi = `Tuo HTML-tiedot`,
  Ui = `Tuo HTML-tiedoista`,
  Wi = `Tuo HTML-tiedoista. HTML-tiedot muunnetaan automaattisesti Steamin muotoilutunnisteiksi.`,
  Gi = `Kirjoita tai liitä HTML-tiedot tähän.`,
  Ki = `Säilytä rivinvaihdot`,
  qi = `Rivinvaihdot eivät muuta HTML-koodia, mutta ne näkyvät BBCode-koodissa tyhjinä riveinä. Jos <p>- tai <br>-tunnisteita on käytetty, älä rastita valintaruutuja. Jos käytät blogiohjelmaa, joka lisää automaattisesti rivinvaihdot <br>-tunnisteilla, rastita ruutu.`,
  Ji = `Muunna BBCode-koodiksi:`,
  Yi = `Muuntaminen käynnissä. Älä sulje valintaikkunaa.`,
  Xi = `Muuntaminen valmis. Valintaikkunan voi sulkea.`,
