  Ph = `Jos käytät päivityksen näkyvyyskierrosta tapahtuman julkaisun jälkeen, tapahtuma näkyy pelisi omistavien tai sen toivelistalle lisänneiden pelaajien "Tuoreet päivitykset" -sivulla.`,
