  Gh = `Kirjasto: Steam-kirjaston kotisivulla (mahdollisesti)`,
  Kh = `Pelaajasi näkevät tämän tapahtuman kirjaston etusivun yläosassa sen perusteella, kuinka monta muuta peliä pelaaja omistaa, sekä jokaisen ilmoituksen ja päivityksen suhteellisen tärkeysjärjestyksen perusteella.`,
