  Qh = `Pohjautuu siihen, kuinka moni omistaa pelin ja näkee sen Steam-kirjastossaan.`,
  $h = `Workshop-sivulla`,
  eg = `Voit myös julkaista tämän tapahtuman/ilmoituksen pelisi Steam Workshopissa. Mene "Asetukset"-välilehdelle ja valitse "Julkaistaanko myös workshopissa?" laittaaksesi vaihtoehdon päälle. Oletuksena pelin tapahtumat/ilmoitukset eivät näy workshop-osiossa.`,
  tg = `Steam-alen tuotesivun banneri`,
  ng = `Tuotesivun banneri näytetään %1$s–%2$s`,
  rg = `Voit luoda Ale-välilehdellä alebannerin, jonka avulla esittelyssä olevat pelit voivat viitata aleen näyttämällä kyseisen bannerin Steamin tuotesivullaan. Banneri auttaa asiakkaita löytämään tietyn pelin alennuksen toivelistasähköpostista tai selaamalla kauppaa, jossa on myös tietoa itse aletapahtumasta. Bannerit näytetään vain aletapahtuman alusta sen loppuun tai kahden viikon ajan, kumpi tapahtuukaan ensin. Tapahtuman aloitus- ja päättymisajat määritetään Asetus-välilehdellä.`,
  ig = `Lähetä sähköposti pelaajille, jotka seuraavat peliä, kehittäjää tai julkaisijaa`,
  ag = `Käsittää kaikki peliin liittyvien kehittäjä- ja julkaisijasivujen ja pelisarjasivujen seuraajat.`,
  og = `Seuraavilla kehittäjä-, julkaisija- ja pelisarjalinkeillä ei ole näkyvää kehittäjän kotisivua. Sellainen auttaisi asiakkaita ymmärtämään tarjontaasi sekä tiedottaisi tapahtumista ja uusista pelijulkaisuista: %1$s`,
  sg = `Uutuus: pelaajien oma tapahtumakalenteri`,
  cg = `Tapahtuma näkyy pelaajien omissa uutiskeskuksissa, jos heillä on pelisi kirjastossa tai toivelistalla tai he seuraavat peliäsi.`,
  lg = `Ilmoitus: mobiili pikailmoitus osallistujille, jotka ovat ottaneet käyttöön`,
  ug = `Tapahtumamuistutuksen valinneiden (ulkoisen kalenterimerkinnän ladanneiden tai tapahtumaa seuraavien) pelaajien lukumäärä.`,
  dg = `sähköpostin saavat pelaajat`,
  fg = `Arvio sähköposteista, jotka sisältävät tapahtuman. Luomme säännöllisesti kullekin asiakkaalle räätälöidyn tapahtumakatsauksen, joka riippuu asiakkaan sähköposti- ja yhteysasetuksista.`,
  pg = `markkinointiviestin saavat pelaajat`,
  mg = `Arvio pelaajista, jotka näkevät tapahtuman omassa Steam-sovelluksen markkinointiviestissään. Kyseessä on ponnahdusikkuna, joka näkyy Steam-työpöytäsovelluksen käynnistyksen yhteydessä. Se kertoo Steam-myynneistä ja mielenkiintoisista tapahtumista.`,
  hg = `tapahtuman ohittaneet pelaajat`,
