  vg = `Näytä dokumentaatio`,
  yg = `Ison päivityksen markkinointiviestiä koskeva tarkistus`,
  bg = `Lähetä tapahtuman markkinointiviesti tarkistettavaksi, kun tapahtuma on valmis eikä muita muutoksia tarvita. Voit vapaasti julkaista ison päivitystapahtuman sen valmistuttua. Ota kuitenkin huomioon, että tarkistus- ja hyväksyntäprosessi voi kestää jopa %1$s arkipäivää.`,
  xg = `Luo pyyntö aloittaaksesi tarkistusprosessin.`,
  Sg = `Luo tarkistuspyyntö`,
  Cg = `Pyyntö on lähetetty. Voit tarkistaa ja päivittää tietoja <1>täällä</1>.`,
  wg = `yhteenveto`,
  Tg = `Näkyvyystilan alkamisajankohta`,
  Eg = `Tämä näkyy heti julkaisun jälkeen useimmissa paikoissa.`,
  Dg = `Huomaa, että moderointitiimi tarkistaa uudet julkaisut julkaisujärjestyksessä. Uutiset ja tapahtumat saattavat näkyä Steam-kirjastossa yli tunnin viiveellä. Jos teet muutoksia näkyviin julkaisuihin, ne palautetaan moderointijonoon.`,
  Og = `Tai korvaa olemassa olevan tapahtuman sisältö`,
  kg = `Epätavallinen toiminto. Mahdollistaa päivitysten esikatselun, jonka jälkeen aiemmin julkaistun tapahtuman sisältö korvataan tällä tapahtumalla. Tämä tapahtuma poistetaan ja sen sisältö korvaa kohteena olevan julkaistun tapahtuman. Kohdetapahtuman tyyppi ja näkyvyysasetukset eivät muutu.`,
  Ag = `Tapahtuma kopioitu kohteesta %1$s`,
  jg = `Korvaa alkuperäinen tapahtuma`,
  Mg = `Sen tapahtuman sisältö, josta tiedot alun perin kopioitiin, korvataan tämän tapahtuman tiedoilla.`,
  Ng = `Huomaa! Alkuperäisen tapahtuman on oltava julkaistu ja yleisesti näkyvissä. Tapahtumaa ei voi korvata, jos se ei ole julkisesti näkyvissä.`,
  Pg = `Muutos tapahtuu välittömästi. Kohdetapahtuman sisältö korvataan ja se tulee heti kaikkien näkyville Steamissä. Nykyinen tapahtuma poistetaan.`,
