  lS = `Valitse tiedosto`,
  uS = `Poista kuva luettelosta`,
  dS = `Poistetaanko kuva lokalisointikielen %1$s tapahtuman otsikkokuvasta? Tämä ei poista taustalla olevaa kuvaa vaan yhteyden tapahtumaan.`,
  fS = `Kuvassa näkyvä punainen neliö vastaa logolle ja tekstille varattua tilaa. Pienempi alue näytetään tietyissä paikoissa, kuten tapahtumaluetteloissa.`,
  pS = `Esimerkki pienennetystä näkymästä`,
  mS = `Kuvan rajattua versiota käytetään ruudukoissa tai useampien tapahtumien riveissä`,
  hS = `Esimerkki lisätietosivun käytöstä`,
  gS = `Koko kuvaa käytetään tapahtuman lisätietosivun ylälaidassa`,
