  ES = `Tapahtuman lisätiedot ja tekstirungon kopio`,
  DS = `Kuvan korkeuden on oltava vähintään 1 920 ja leveyden 800. Kokoa voi kasvattaa joko yhteen tai molempiin suuntiin.`,
  OS = `Sovelluksen metadatan muokkaus`,
  kS = `Antaa oikeuden ladata depotteja, testata Steamworks-toimintoja, määrittää paketteja, saavutuksia ja pistetaulukkoja, julkaista keräilykortteja jne. Antaa lisäksi ylläpito-oikeuden ja oikeuden hyväksyä ryhmän Steam-yhteisön hakemukset.`,
  AS = `Julkaise sovellusmuutokset Steamiin`,
  jS = `Antaa oikeuden julkaista Steamworks-kehittäjäsivustolla (Tekniset työkalut > Muokkaa Steamworks-asetuksia) tuotteeseen tehtyjä muutoksia.`,
  MS = `Virhetietojen selaus`,
  NS = `Antaa oikeuden katsoa tuotteen virheraportteja (jos tuote on yhdistetty Steamworks-virheilmoitusjärjestelmään).`,
  PS = `Pelien lataus Steamin kautta`,
  FS = `Lisää tuotetunnuksia järjestelmään`,
