  BS = `Hallinnoi pelin CEG:tä`,
  VS = `Voi hallita CEG-asetuksia (Custom Executable Generation) ja niiden integrointia nimikkeeseen.`,
  HS = `Allekirjoitusten hallinnointi`,
  US = `Voi hallinnoida tuotteen digitaalista allekirjoitusta. Tuotteen huijaukseneston ja SDK-todennusasetusten hallinnointi otetaan käyttöön.`,
  WS = `Tuotetunnusten hallinnointi`,
  GS = `Sovelluksen markkinointitietojen muokkaus`,
  KS = `Antaa oikeuden muokata ja julkaista kauppasivun tietoja, esim. pelin kuvauksen, markkinointikuvia ja videoita. Antaa lisäksi luvan käyttää kaupan markkinointitoimintoja, kuten näkyvyyskierroksia.`,
  qS = `Kaupan lokalisointitietojen muokkaus`,
  JS = `Myöntää luvan kauppasivun lokalisoitujen asetusvälilehtien kuten tuotekuvauksen tai graafisten elementtien muokkaamiseen. Ei myönnä lupaa julkaisuun tai pääsyä markkinointityökaluihin kuten näkyvyyskierroksiin. Huomaa: tämä on Muokkaa sovelluksen markkinointitietoja -toiminnon alatoiminto.`,
  YS = `Talouden ja workshopin tuki`,
  XS = `Sallii käyttäjän selata/myöntää taloudellista hyötyä tarjoavia esineitä yhteistyökumppanisivuston taloustyökalulla.`,
  ZS = `Talouden ja workshopin valvoja`,
  QS = `Samat toiminnot kuin talouden ja workshopin tuella yllä.`,
  $S = `Hintojen ja alennusten muokkaus`,
