  sC = `Nimenkirjoitusoikeus`,
  cC = `Julkaisijan kattava: nämä käyttäjät voivat muuttaa maksutietoja (esim. pankkitili- ja verotietoja) ja siirtää omistusoikeuksia.`,
  lC = `Näytä taloustiedot (julkaisijan laajuinen)`,
  uC = `Kumppanin laajuinen: nämä käyttäjät voivat nähdä myyntitilastoja ja taloustietoja mistä tahansa tämän julkaisijan ylläpitämistä sovelluksista.`,
  dC = `Lompakon varojen hyväksyntä`,
  fC = `Nämä käyttäjät pystyvät hyväksymään asiakkaan lompakkovarojen siirrot.`,
  pC = `Hallinnoi lisensoituja toimipaikkoja`,
  mC = `Nämä käyttäjät voivat nähdä ja hallinnoida lisensoitujen toimipaikkojen sijaintitietoja, käyttöoikeuksia ja toimintaa.`,
  hC = `Steamworks-viestinnän vastaanotto`,
  gC = `Käyttäjille lähetetään tietoa tulevista alekampanjoista ja kohdistetuista tapahtumista sekä Steamin uusien toimintojen ilmoituksia sähköpostitse.`,
  _C = `Käyttäjälle on lähetetty kutsu, jolla hän voi saada Steamworks-viestintäoikeudet, mutta hän ei ole vielä hyväksynyt kutsua.`,
  vC = `Ota alesivu käyttöön`,
  yC = `Alesivulle tulee lisätä seuraavat kaksi kohtaa:`,
  bC = `Anna räätälöity (Vanity) nimi, joka näkyy URL-osoitteen lopussa. Ilman tätä Steamin asiakkaat eivät pääse alesivulle.`,
