  CC = `Alen päättymisaika`,
  wC = `Ota päivityssivu käyttöön`,
  TC = `Päivityssivua varten tarvitaan mukautettu nimi, joka näkyy kauppasivun URL-osoitteessa. Steam-käyttäjät pääsevät päivityssivulle klikkaamalla linkkiä.`,
  EC = `Otetaanko kauppasivun editori käyttöön tapahtumalle?`,
  DC = `Haluatko ottaa päivityssivun käyttöön tälle tapahtumalle?`,
  OC = `Valitse oletusotsikoista:`,
  kC = `Oletusotsikkoa ei käytetä, koska räätälöity otsikko nykyisellä kielellä tai englanniksi on jo käytössä`,
  AC = `Tai aseta räätälöity otsikko`,
  jC = `Syötetyt räätälöidyt otsikot:`,
  MC = `(Vain Valve) Lähetä räätälöidyt otsikkokuvat. Otsikon teksti: img alt text.`,
  NC = `Näytä erityinen taso otsikossa (esimerkiksi Steamin halloweenin 2019 kummitustalo)`,
