  FC = `Pikselisiirtymä`,
  IC = `Pikselipoikkeama on poistettu käytöstä, koska alesivun logo on saatavilla. Logon pikselipoikkeama käsitellään automaattisesti.`,
  LC = `Pikselien määrä, jolla alesivun sisältöä siirretään alaspäin, jotta sen taustakuvassa on tilaa otsikolle ja päivämäärille. Sitä ei tarvitse säätää kuin erityistilanteissa.`,
  RC = `Oletusarvon (ja enimmäisarvon) tulee olla %1$s.`,
  zC = `Tämä varmistaa alesivun toiminnan, kun sitä katsellaan Steam Deckissä tai tabletilla.`,
  BC = `(Vain Valve) Rajoitetaanko sivu vain sovelluksen omistaville?`,
  VC = `Lukitulle sivulle pääsyyn vaaditaan tilauksen vahvistus. Muut kuin tilaajat ohjataan toisaalle (esim. kauppasivulla).`,
