  UC = `Salli vain sovellusten (tai toisen listan pakettien) omistajien katsella sivua.`,
  WC = `Vaaditut pakettitunnukset`,
  GC = `Muokkaa tunnistekuvan asettelua niin, että siitä löytyy Lisää kirjastoon / Pelaa nyt -painike hintojen ja Lisää ostoskoriin -painikkeen sijaan.`,
  KC = `Uudelleenohjauksen URL-osoite`,
  qC = `Muut kuin omistajat ohjataan tälle sivulle`,
  JC = `Käytä tilausasettelua`,
  YC = `Salli vain pakettien (tai toisen listan sovellusten) omistajien katsella sivua.`,
  XC = `Huomaa! Tapahtumalta puuttuu Valven hyväksymä tarjoustoiminto. Vain Valve voi ottaa tarjoustoiminnon käyttöön suljetussa betassa. Ota yhteyttä Valveen ja pyydä tarjoussivun käyttöönottoa tapahtumalle.`,
  ZC = `(Vain Valve) Rajoitetaanko sivu vain sovelluksen muokkaajille?`,
  QC = `Lukitsee sivun niin, että kumppanin sovellusmuokkaus tulee tarkistaa tietyille sivulla esitellyille peleille.`,
  $C = `Suoratoistot`,
  ew = `Määritä tämän aletapahtuman muut striimausasetukset Striimaus-välilehdellä.`,
  tw = `Striimaus ei ole aletapahtuman käytössä.`,
  nw = `Ota Striimaus-välilehdeltä striimaus aletapahtuman käyttöön. Sen jälkeen voit muokata striimausasetuksia tällä sivulla.`,
  rw = `Näytä ainoastaan sallitut striimit Striimaus-välilehdellä.`,
  iw = `Steam näyttää oletuksena kaikki peliisi liittyvät suoratoistot tarjoussivullasi. Muita toimenpiteitä ei vaadita, jos nämä oletusarvot sopivat tarjoustapahtumaasi. Jos haluat erikseen hallinnoida mitkä suoratoistot näytetään tarjoussivullasi, käytä tätä merkintää ja tee valintasi Suoratoisto-välilehdellä.`,
  aw = `Sivun yleisasetukset`,
  ow = `Kehittäjän kotisivun opas`,
  sw = `Näytetäänkö kehittäjän tunnistekuva tälle tapahtumalle?`,
  cw = `Kun valinta on käytössä, tiedot tekijästä näytetään sivun alalaidassa.`,
  lw = `Hallinnoidut mukautetut osion taustatyylit`,
  uw = `Luo yksi tai useampi mukautettu osion taustatyyli tässä valintaikkunassa. Tyylit voidaan valita mille tahansa sivun osiolle. Kun tyyliä muutetaan täällä, päivitys otetaan välittömästi käyttöön kaikissa kyseistä tyyliä käyttävissä osioissa. Näin sinulla on mahdollisuus hallinnoida useiden osioiden ulkoasua kerralla ja pitää ne johdonmukaisina.`,
  dw = `Tyylejä ei ole luotu.`,
  fw = `Muokattava tyyli: %1$s`,
