  mw = `Linkitetyt sovellukset – %1$s`,
  hw = `Linkitetyt sovellukset: %1$s (%2$s suodatettu pois)`,
  gw = `Alessa olevien, nimikkeillä varustettujen tuotteiden määrä. Nimikkeiden avulla määritellään, mitkä tuotteet näytetään missäkin osioissa.`,
  _w = `Hae listalta`,
  vw = `Hae nimellä`,
  yw = `Rajaa alta löytyvästä nimikkeillä merkittyjen tuotteiden listasta vain ne, jotka vastaavat tätä tekstiä.`,
  bw = `Muokkaa useita merkintöjä kerralla`,
  xw = `Syötä muokattavat tuotteet`,
  Sw = `Tähän voi syöttää listan tunnuksia, joita muokataan nimikkeiden lisäämiseksi tai poistamiseksi. Tämä on suunniteltu yleisesti kopioi/liitä-tyylisille tuotelistoille.`,
