  Mw = `Nimikkeet, jotka on määritelty muille alen tuotteille tai kaupan tuotteelle, mutta joita ei käytetä tälle tuotteelle tässä alessa.`,
  Nw = `Viimeisimmät nimikkeet`,
  Pw = `Olet lisännyt nämä nimikkeet hiljattain tämän alen tuotteisiin. Niiden avulla pääsee nopeasti yleisimpiin nimikkeisiin.`,
  Fw = `Osiot – %1$s`,
  Iw = `Lista kaikista osioista, joissa tuote näkyy siihen liitettyjen nimikkeiden perusteella.`,
  Lw = `Lisää nimike`,
  Rw = `Voit hakea käytössä olevia nimikkeitä tai luoda uusia. Nimikkeet voi myös valita Muut nimikkeet -sarakkeesta oikealta.`,
  zw = `Poista nimike`,
  Bw = `Poistaa nimikkeen kaikilta valituilta tuotteilta.`,
  Vw = `Lisää`,
  Hw = `Voit lisätä tai tuoda listan tuotteita esiteltäviksi alesivulla ja merkitä tuotteet nimikkeillä. Sitten voit määritellä osiot lisäämään sisältöä automaattisesti asettamalla nimikkeille suodattimet. Toiminto on tarkoitettu suuremmille aletapahtumille, joissa on satoja tuotteita. Se saattaa olla turhan monimutkainen pienemmille aletapahtumille.`,
  Uw = `Nämä sovellukset on linkitetty kehittäjän kotisivullesi. Voit viitata peleihin sivulla käyttämällä joko älykästä osiota tai viittaamalla niihin manuaalisesti.`,
