  cD = ` Välilehdillä: %1$s`,
  lD = `Päätilauksen tunnus (valinnainen)`,
  uD = `Jos määritetty, kyseiseen päätilauksen tunnukseen sisältyvät esineet lisätään selailupaneeliin.`,
  dD = `Pelit sivua kohden`,
  fD = `Jos arvoksi asetetaan nolla, käyttöön otetaan järkeenkäypä oletusluku (12 tuotetta). Muussa tapauksessa sivu pyrkii lataamaan valitun määrän sovelluksia sivua kohti ennen kuin Näytä lisää -painike tulee näkyviin.`,
  pD = `Välilehdet`,
  mD = `Selailuasetuksissa näkyvät välilehdet ja niiden järjestys.`,
  hD = `Käytöstä poistetut välilehdet`,
  gD = `Lisävälilehdet, jotka voidaan lisätä näytettäviksi, mutta joita ei muuten käytetä tässä osiossa.`,
  _D = `Tapahtumat – %1$s`,
  vD = `< Valitse tyyppi >`,
  yD = `Sovellukset ja myyntipaketit`,
  bD = `Tämä osio näyttää sivun pelit, paketit ja myyntipaketit. Osioita kannattaa luoda useampi niin, että jokaisessa näkyy eri pelejä.`,
  xD = `Pelit, lisämateriaalit ja demot`,
  SD = `Tämä osio näyttää sivun pelit. Osioita kannattaa luoda useampi niin, että jokaisessa näkyy eri pelejä.`,
  CD = `Uutiset ja tapahtumat`,
  wD = `Näyttää valitsemasi Steam-tapahtumat ja -ilmoitukset sivulla.`,
  TD = `Kuvat`,
  ED = `Näyttää yhden tai useamman kuvan yksittäisenä elementtinä, karusellissa tai ruudukossa. Valinnaisesti on myös mahdollista tarjota kuvien lokalisoidut versiot sekä linkittää kuvat kaupan muihin osiin.`,
  DD = `Näyttää yhden tai useamman kuvan yksittäisenä kohteena, karusellissa tai ruudukossa. Voit halutessasi lisätä kuvien lokalisoidut versiot.`,
  OD = `Otsikko- tai ylätunnistekuva`,
  kD = `Näyttää yksittäisen lokalisoitavan kuvan, jota käytetään ylätunnisteena tai otsikkona.`,
  AD = `Ristiinmarkkinoitava alesivu`,
  jD = `Pienoisohjelma hakee pelit automaattisesti aiheeseen liittyvältä jo julkaistulta alesivulta. Varmista, että sisältö sopii alesivun teemaan.`,
  MD = `Striimisoitin`,
  ND = `Jos striimi on otettu sivun käyttöön, videosoittimet näkyvät oletuksena sivun ylälaidassa. Pienoisohjelman avulla voit päättää, missä kohtaa sivua haluat videosoittimen näkyvän.`,
  PD = `Tapahtuman kuvaus`,
  FD = `Lisää sivulle kuvausvälilehdeltä löytyvän tekstin.`,
  ID = `Päivittäiset palkinnot`,
  LD = `Muokkaa sivun kuvausta kuvausvälilehdellä.`,
  RD = `Teksti`,
  zD = `Näyttää muotoilua, kuvia ja videoita tukevan tekstialueen.`,
  BD = `Kehittäjän tai julkaisijan kotisivu tai yhteisöryhmän pienoisohjelma`,
  VD = `Näyttää tietyn Steam-yhteisöryhmän tai kehittäjän/julkaisijan kotisivun nimellä, kuvauksella ja Seuraa-painikkeella varustetun widgetin.`,
  HD = `Kuraattori: %1$s`,
  UD = `Pelitrailerikaruselli`,
  WD = `Laaja trailerinäkymä, joka toistaa ensin mikrotrailerin ja sitten ensisijaisen kauppasivun trailerin. Pelin tiedot näkyvät oikealla.`,
  GD = `Sovellukset näkyvät osiossa vain, jos niille on olemassa traileri.`,
  KD = `Näytä yksittäinen kehittäjälista`,
  qD = `Näyttää kehittäjälistojen karusellin, joka on määritelty kehittäjän kotisivun asetusten Hallinnoi listoja -osiossa.`,
  JD = `Näytä kaikki kehittäjälistat`,
  YD = `Näyttää kaikkien kehittäjälistojen karusellin, joka on määritelty kehittäjän kotisivun asetusten Hallinnoi listoja -osiossa.`,
  XD = `Kuraattorien suositukset ja listat`,
  ZD = `Hallinnoi kuraattorien suositusten tai ominaisuuslistojen näkymiskohtaa sivulla. Oletuksena Steam-kuraattoreita seuraavat käyttäjät näkevät seuraamansa kuraattorin suositukset alessa esitellyistä peleistä alennussivun alareunassa. Tämän avulla voit päättää, missä osio näkyy.`,
  QD = `Näyttää kuraattorien suositukset ja listat. Hakee automaattisesti käyttäjän seuraamien kuraattorien listat sekä valitsemasi esiteltävän listan käyttäjän valitsemalla kielellä.`,
  $D = `Valinnainen: näkymisen aloitusaika`,
  eO = `Voit halutessasi määrittää ajan, jolloin suositukset tulevat näkyviin. Näin annat kuraattoreille enemmän aikaa koota listojaan ennen kuin ne tulevat näkyviin. Määtitetyn ajan tulee sijoittua tapahtuman alkamis- ja päättymisaikojen välille.`,
  tO = `Esiteltävä kuraattorin suosituslista:`,
  nO = `Voit valita alennusta varten luodut kuraattorien listat. Kuraattorit voivat luoda listoja vasta alen alettua.`,
  rO = `Valitse esiteltävä lista`,
  iO = `Kuraattorit voivat luoda alessa esiteltävien pelien listan. Valintaikkunan avulla voi valita yhden tai useamman listan esiteltäväksi sivulla. Esiteltävä lista näytetään kaikille sivulla vieraileville Steamin käyttäjille.`,
  aO = `Kuraattoria ei voi valita. Alen on oltava julkinen ja käynnissä.`,
  oO = `Välilehdet`,
  sO = `Rivi painikkeita, joilla hallinnoidaan alla olevaa sisältöä sivulla`,
  cO = `Välilehden painikkeet`,
  lO = `Valinnainen osio, joka on käytössä vain olemassaolevalle välilehdelle. Osio kannattaa sijoittaa sivun loppuun, jolloin välilehdet näkyvät painikkeina. Ne on helppo löytää, jos välilehtiä ei huomannut aiemmin sivulla.`,
  uO = `Monivalintatehtävät`,
  dO = `Osio, jossa voi tarjota asiakkaille visailutyyppisiä monivalintatehtäviä.`,
  fO = `Pistekaupan älykäs osio`,
  pO = `Tätä osiota varten vaaditaan luokkatunniste. Luokkatunnisteen avulla näytetään automaattisesti pistekaupan esineet, joissa on sopivat tunnisteet.`,
  mO = `Yhteisöesineluokka`,
  hO = `Rajoittaa näkyvät pistekaupan esineet tähän luokkaan. Valinta on pakollinen. Huomaa: profiilin muokkaajaa kutsutaan myös peliprofiileiksi.`,
  gO = `Pistekaupan luokkatunniste`,
  _O = `Määrittää, mikä tunnisteluokka pistekaupan esineille näytetään. Tunniste on luultavasti tapahtuman osallistumisnimi, kuten sale_halloween_2022.`,
  vO = `Löytöjono`,
