  bO = `Löytöjonotyyppi`,
  xO = `Löytöjonokuvaus`,
  SO = `Tämä kuvaus näytetään, kun löytöjono suljetaan. Se sisältää oletuksena kuvauksen uusista julkaisuista, joka voidaan ohittaa.`,
  CO = `Uutta`,
  wO = `Pelit, lisämateriaalit, ohjelmat ja videot (pois lukien demot). Lajitellaan suurpiirteisesti julkaisupäivän ja myyntitason perusteella.`,
  TO = `Tulossa pian`,
  EO = `Julkaisemattomat pelit, demot, lisämateriaalit ja videot. Lajitellaan suurpiirteisesti toivelistan sijoituksen perusteella.`,
  DO = `Suositellut`,
  OO = `Pelit, ohjelmat ja videot, jotka sisältävät käyttäjälle suositeltuja tunnisteita. Lajitellaan suurpiirteisesti tunnisteen ja myyntitason perusteella.`,
  kO = `Suositellut tulevat julkaisut`,
  AO = `Julkaisemattomat pelit, ohjelmat ja videot, jotka sisältävät käyttäjälle suositeltuja tunnisteita. Lajitellaan suurpiirteisesti tunnisteen ja toivelistan sijoituksen perusteella.`,
  jO = `Suositellut ilmaistuotteet`,
  MO = `Ilmaiset pelit, ohjelmat ja videot, jotka sisältävät käyttäjälle suositeltuja tunnisteita. Lajitellaan suurpiirteisesti tunnisteen ja päivittäisen käyttäjämäärän perusteella.`,
  NO = `Suositellut tarjoukset`,
  PO = `Tarjouksessa olevat pelit, ohjelmat ja videot, jotka sisältävät käyttäjälle suositeltuja tunnisteita. Lajitellaan suurpiirteisesti tunnisteen ja myyntitason perusteella.`,
  FO = `Suositellut demot`,
  IO = `Demot, jotka sisältävät käyttäjälle suositeltuja tunnisteita. Lajitellaan suurpiirteisesti tunnisteen ja päivittäisen käyttäjämäärän perusteella.`,
  LO = `Johdantovideon sisältävä sovellus`,
  RO = `Määritä sovellustunnus, jonka traileri näkyy ennen muita trailereita silloin, kun käyttäjä vierailee sivullasi ensimmäistä kertaa.`,
  zO = `Esittelytrailerin perustunnus`,
  BO = `Tämä on yllä olevalle sovellustunnukselle kuuluva trailerin perustunnus.`,
  VO = `Alessa on useita trailerikaruselleja, ja niille asetetut esittelyvideosovellukset eivät täsmää. Tämä on epätavallinen tapa määrittää sivu ja voi johtua virheestä.`,
  HO = `Sovelluksella ei ole trailereita, eikä se näy tässä osiossa.`,
  UO = `Sovelluksella ei ole kaikenikäisille suunnattuja trailereita, ja se näkyy tässä osiossa vain, jos käyttäjä on sallinut aikuisille suunnatun sisällön.`,
  WO = `<1>Listoja voi hallinnoida</1> kehittäjän kotisivun työpöydällä.`,
  GO = `<1>Listoja voi hallinnoida ja järjestää uudelleen</1> kehittäjän kotisivun työpöydällä.`,
  KO = `Piilotettuja listoja ei näytetä sivullasi.`,
  qO = `Nykyiset kehittäjälistat:`,
  JO = `Osio piilotetaan, koska sinulla ei ole näkyviä listoja.`,
  YO = `Merkin edistyminen`,
  XO = `Merkin edistymisnäytön editori. Antaa määrittää tapahtumakohtaisen, ansaittavan merkin, jonka tasoa voi korottaa.`,
  ZO = `Sisäinen aleosio (useita vaihtoehtoja saatavilla)`,
  QO = `Poista välilehti`,
  $O = `Oletko varma, että haluat poistaa välilehden %1$s?`,
  ek = `Lisää välilehti`,
  tk = `Toiminto lisää uuden välilehden, jolle voi antaa nimen ja tuotelistan, jolla voi suodattaa alla olevia aleosioita.`,
