  ak = `Valitun välilehden otsikko`,
  ok = `Valitse välilehdelle valmiiksi käännetty otsikko tai oma otsikko ja anna haluamasi nimi kaikille kielille`,
  sk = `Suodata näyttämään vain tällä välilehdellä näkyvät osiot`,
  ck = `Näyttää väliaikaisesti vain editorin tällä välilehdellä näkyvät osiot. Kyseessä on pelkkä muokkauksen aikainen ominaisuus.`,
  lk = `Piilota välilehti`,
  uk = `Välilehden näkyvyys`,
  dk = `Tämä asetus määrittää, näytetäänkö käyttäjälle myyntisivun välilehteä.`,
  fk = `Otetaanko maan näkyvyysasetukset käyttöön?`,
  pk = `Sallittujen maiden lista`,
  mk = `Lista koostuu pilkuilla erotetuista kaksikirjaimisista maakoodeista. Se näkyy ainoastaan sallituissa maissa.`,
  hk = `Estettyjen maiden lista`,
  gk = `Lista koostuu pilkuilla erotetuista kaksikirjaimisista maakoodeista. Se näkyy ainoastaan kielletyissä maissa.`,
  _k = `Otetaanko paketin näkyvyysasetukset käyttöön?`,
  vk = `Sallittujen pakettien luettelo`,
  yk = `Tämä on pilkuilla toisistaan erotettujen pakettitunnusten luettelo. Välilehti tulee näkyviin ainoastaan, jos katsojalla on jokin luettelossa mainituista paketeista.`,
  bk = `Otetaanko laitteiston käytön näkyvyysasetukset käyttöön?`,
  xk = `Tämä välilehti tulee näkyviin ainoastaan, jos tietoja tarkasteleva käyttäjä on käyttänyt mainittuja laitteistoja. Jos jokin vaihtoehdoista on valittu, osio ei näy uloskirjautuneille käyttäjille.`,
  Sk = `Lista sallituista käytetyistä laitteistoista`,
  Ck = `Nykyiset välilehdet`,
  wk = `Jokainen välilehti määrittää nimetyn sisältökokoelman, joka suodattaa seuraavista osiosta näkyviin vain kyseiset sisällöt.`,
  Tk = `Välilehdet ovat suodatintyyppi, joka määrittää näytettävät osiot. Määritä välilehdet täällä ja siirry sen jälkeen muihin osioihin valitsemaan välilehdet, joilla osiot tulevat näkyviin. Osiot näkyvät oletusarvoisesti kaikilla välilehdillä.`,
  Ek = `Välilehden valitseminen tässä näyttää vain editorin kyseisellä välilehdellä näkyvät osiot. Kyseessä on pelkkä muokkauksen aikainen ominaisuus.`,
  Dk = `%1$s välilehti`,
  Ok = `%1$s välilehteä`,
  kk = `Välilehden värit`,
  Ak = `Ei-aktiivisen välilehden värit`,
  jk = `Säädä oletusvälilehden värejä`,
  Mk = `Aktiivisen välilehden värit`,
  Nk = `Säädä valitun välilehden värejä`,
  Pk = `Säädä oletusvälilehden ja valitun välilehden värejä`,
  Fk = `Valinta- ja korostusväri`,
  Ik = `Ohita välilehtien oletusarvoiset korostus- ja valintavärit. Palauta oletusvärit poistamalla valinta.`,
  Lk = `Suodatetun tuotelistan sisältävä välilehti`,
  Rk = `Seuraavia tuotteita käytetään suodattimina. Kun välilehti on valittuna, seuraavissa osioissa näytetään vain listalta löytyviä tuotteita.`,
  zk = `Välilehden %1$s tuotteiden lukumäärä: %2$s`,
  Bk = `%1$s – näytä kaikki tuotteet`,
  Vk = `Välilehti on määritetty näyttämään seuraavissa osioissa kaikki tuotteet, mutta voit luoda listan niistä klikkaamalla alla. Niin vain sillä listalla näkyvät tuotteet näytetään seuraavissa osioissa, kun välilehti on aktiivinen.`,
  Hk = `Muokkaa suodatettuja tuotteita`,
  Uk = `Valitun välilehden taustakuva (valinnainen)`,
  Wk = `Mahdollistaa välilehden taustakuvan asettamisen, joka näytetään välilehden ollessa valittuna. Kuva täyttää välilehtipalkin sivun ylälaidassa.`,
  Gk = `Huomaa: suodattimet lisäävät automaattisesti Näytä Deck-yhteensopivuus -ikkunan, joka näkyy hiiren ollessa tunnistekuvan päällä.`,
  Kk = `Huomaa! Suodattimet lisäävät automaattisesti Näytä Frame-yhteensopivuus -ikkunan, joka näkyy hiiren ollessa tunnistekuvan päällä.`,
  qk = `Huomaa! Suodattimet lisäävät automaattisesti Näytä Machine-yhteensopivuus -ikkunan, joka näkyy hiiren ollessa tunnistekuvan päällä.`,
  Jk = `Huomaa: suodattimet lisäävät automaattisesti Pelaa demoa -toiminnon, joka näkyy hiiren ollessa tunnistekuvan päällä.`,
  Yk = `Huomaa: suodattimet piilottavat tämän välilehden automaattisesti käyttäjiltä, joiden asetukset eivät salli aikuissisältöä.`,
  Xk = `Huomaa! Suodatin poistaa automaattisesti tuoteselaimen välilehdet, jotka eivät koske tulevia tuotteita.`,
  Zk = `Ohitusvalikko`,
  Qk = `Ohitusvalikko näkyy välilehtien alla ja helpottaa välilehtien alla oleviin osioihin siirtymistä. Tästä on hyötyä silloin, kun välilehti sisältää useita eri osioita. `,
  $k = `Välilehdellä on %1$s osio(ta), joille on määritetty %2$s ankkurimerkki. Ohitusvalikko tarvitsee ankkurimerkin kohteekseen. `,
  eA = `Luo ohitusvalikkoja käyttääksesi vähintään yhden osion ankkuri osion nimieditorissa. `,
  tA = `Ota ohitusvalikko välilehden käyttöön`,
  nA = `Poista välilehden ohitusvalikko`,
  rA = `Välilehden ohitusvalikko poistetaan. Toimintoa ei voi perua ilman, että editori ladataan uudelleen. Oletko varma?`,
  iA = `Ohitusvalikon kohteen nimi`,
  aA = `Ei ohitusvalikon kohteita`,
  oA = `Lisää ohitusvalikon kohteita`,
  sA = `Jätä tyhjäksi käyttääksesi osion otsikkoa`,
  cA = `Tunnistesuodatin`,
  lA = `Välilehdillä näkyvä tunnistesuodatin antaa katsojan tiivistää tämän välilehden jokaisen osion tunnisteeseen, ja sen jälkeen kyseisen tunnisteen alatunnisteeseen.`,
  uA = `Lajityypit ja alalajityypit`,
  dA = `Teemat`,
  fA = `Ominaisuudet`,
  pA = `Tämä välilehti käyttää sisäänrakennettuja tunnisteita (%1$s). Tuo ne alle muokataksesi niitä täällä.`,
  mA = `Tuo sisäänrakennetut tunnisteet`,
  hA = `Korvaa tämän välilehden tunnisteet valitun sisäänrakennetun luokan muokattavalla kopiolla.`,
  gA = `Tuo (korvaa tämän välilehden nykyiset tunnisteet)`,
  _A = `Lisää tunniste`,
  vA = `Lisää alatunniste`,
  yA = `Alatunnisteet: %1$s`,
  bA = `Poistetaanko tunniste?`,
