  fI = `Taustan liukuväri (alaosa)`,
  pI = `Osion taustakuva`,
  mI = `Lataa kuva, joka näytetään tämän osion taustalla taustavärin sijaan. Kuva toistetaan vierekkäin, jos se on liian pieni, eikä täytä koko tilaa.`,
