  kG = `Mahdolllistaa tarjouksessa olevien, linkitettyjen tuotteiden listan suoran muokkaamisen. Toimintoa voi hyödyntää tiedostojen tuomiseen tai viemiseen esimerkiksi Excelistä tai isojen muutosten tekemiseen tuotelistalla.`,
  AG = `Räätälöidyt nimikkeet`,
  jG = `Pääset muokkaamaan tämän alennuksen linkitettyjen tuotteiden listaa suoraan ja voit tuoda ja viedä aletuotteiden räätälöityjen nimikkeiden kokoelman. Tätä käytetään ensisijaisesti ulkoisen taulukon avulla hallittavan, räätälöityjen nimikkeiden kokoelman tuomiseen ilman, että muita nimikkeitä muokataan. Valintaikkunan avulla voidaan myös tuoda pienempi joukko nimikkeitä, sillä tämä ei poista listaamattomia tuotteita.`,
  MG = `Tuo ilmoittautumissivulta`,
