  dq = `Määrittää, minä alennuksen päivänä tietyt tuotteet esitellään. Lähtökohtaisesti ne näytetään joka päivä, mutta tällä voit rajoittaa valittujen tuotteiden näkyvyyttä vain tietyille päiville.`,
  fq = `Päivittäin vaihtuva alepäivän taustakuva`,
  pq = `Jos käytetään oletusvalintaa "1", alekampanjan aikana näytetään vain yksi ylätunnisteen taustakuva. Jos asetuksena on suurempi luku, eri päivinä näytetään eri kuva. Viimeisen päivän kuva jää kampanjan päätyttyä näkyviin. Saatavilla olevien taustakuvien määrä riippuu Asetukset-välilehdessä määritellyn tapahtuman kestosta.`,
  mq = `%1$s alen ylätunnistekuvaa`,
