  gq = `Asetuksen muuttaminen poistaa kaikki aiemmat alen ylätunnistekuvat tästä tapahtumasta. Jatketaanko?`,
  _q = `Minkä päivän kuvan haluat näyttää/päivittää?`,
  vq = `Esikatselu näyttää lähetetyt kuvat valitulle päivälle. Myös mitkä tahansa ylätunnisteeseen liittyvät kuvat lisätään tällä hetkellä valittuna olevaan päivään.`,
