  jq = `Ei sallittu`,
  Mq = `Kohdetta ei voi lisätä, koska sitä ei ole linkitetty kehittäjän, julkaisijan tai pelisarjan kotisivulle. Linkitä kohde ja lataa alesivu uudelleen yhteyden päivittämiseksi.`,
