  Fq = `Paketti ei sallittu`,
  Iq = `Pakettia ei voi lisätä, koska sitä ei ole linkitetty kehittäjän, julkaisijan tai pelisarjan kotisivulle. Linkitä kohde ja lataa alesivu uudelleen yhteyden päivittämiseksi. Sovelluksia ei ole linkitetty kehittäjään: (%1$s).`,
