  Qq = `Priorisoi myyntituloja`,
  $q = `Oletusasetus. Käyttää tietoja nousussa olevista aletapahtumista priorisoimaan asiakkaiden näkemiä, ristiinmarkkinoidulta alesivulta lähtöisin olevia pelejä.`,
  eJ = `Kun alessa on useampia sivuja, osio muutetaan karuselliksi. Karusellin kohdat ovat yksittäisiä alesivuja, jotka näkyvät tässä järjestyksessä. Muuta järjestystä klikkaamalla ja vetämällä.`,
