  eY = `Fasettiarvon nimi. Fasettiarvo on erillinen vaihtoehto, jolla käyttäjä voi suodattaa osiossa näytetyt pelit. Esimerkiksi "1. persoona".`,
  tY = `Fasettiarvon oikealla puolella näytettävä valinnainen teksti, jolla voidaan antaa fasettiarvolle lyhyt kuvaus. Esimerkiksi "1–2 tuntia" lyhyen peliajan pelien fasettiarvolle.`,
  nY = `Fasetin nimi. Fasetti on joukko samankaltaisia vaihtoehtoja, joilla käyttäjä voi suodattaa osiossa näytetyt pelit. Esimerkiksi "lajityyppi".`,
  rY = `Lisätään automaattisesti fasetit ja fasettiarvot kaupan tunnisteluokkien perusteella, kuten "lajityyppi" ja "visuaalisuus ja näkökulmat". Automaattisen luomisen jälkeen fasetteja ja fasettiarvoja voi muokata manuaalisesti.`,
  iY = `Poista fasettiarvot, jotka eivät sovi mihinkään osion tuotteisiin.`,
  aY = `Minkä vähimmäismäärän haluat valittuun sarakkeeseen näkyville hakutuloksille? Tämä piilottaa vasemmasta valikosta kaikki hakusanat, jotka eivät sisällä vähintään näin monta vastaavaa kohdetta. Määrä lasketaan välilehtisuodattimien käytön jälkeen. Noin viisi on usein sopiva luku.`,
  oY = `Näytä korkeintaan näin monta vaihtoehtoa minkä tahansa ylätason luokan vasemmassa valikossa. Älä esimerkiksi näytä enempää kuin näin monta lajityyppiä Lajityyppi-fasetin alla. Noin viisi on usein sopiva luku.`,
  sY = `Lajittele kunkin fasetin arvot tämän mittarin mukaan. Paras vaihtoehto on yleensä täsmäävyyden perusteella.`,
  cY = `Järjestä kunkin fasetin sisäiset fasettiarvot nimenmukaisessa aakkosjärjestyksessä.`,
  lY = `Valitse kunkin fasetin sisällä fasettiarvot alenevassa järjestyksessä, joka perustuu niitä vastaavaan tuotemäärään. Esimerkiksi "lajityyppi"-fasetin alla "RPG" näytetään ennen "strategiaa", jos osiossa on enemmän RPG- kuin strategiapelejä.`,
  uY = `Älä lajittele fasettiarvoja. Ne näytetään alla olevien listojen määrittämässä järjestyksessä.`,
  dY = `Korostettu fasettiväri`,
  fY = `Otsikon väri`,
  pY = `Oletusarvoisesti käytössä`,
  mY = `Synkronoi 20 suosituinta kauppatunnistetta`,
  hY = `Vain 10 suosituinta kauppatunnistetta synkronoidaan oletuksena joka tuotteelle. Valitse tämä, jotta sen sijaan synkronoidaan 20 suosituinta tunnistetta.`,
  gY = `Luo tietoa vianetsintää varten`,
  _Y = `Looginen AND`,
  vY = `Jos valittuna, käyttäjän valitessa fasetissa useita fasettiarvoja kyseiseen suodattimeen käytetään loogista AND-operaattoria (JA). Muuten fasettien arvojen suodattamiseen käytetään loogista OR-operaattoria (TAI).`,
  yY = `Aluksi laajennettu`,
  bY = `Jos vaihtoehto on valittu, fasetti näkyy laajennettuna selaimen ensimmäisellä avauskerralla.`,
  xY = `Valitse yksittäinen`,
