  PY = `Sisältökeskuksen toissijainen näyteikkuna`,
  FY = `Esineen määritys (virtuaaliset esineet)`,
  IY = `Pelin määrittämät virtuaaliset esineet, joita hallinnoi joko tavaraluettelopalvelu tai kumppanin peliin liittyvän talouden omat elementtipalvelut`,
  LY = `Valitut virtuaaliset esineet:`,
  RY = `Sallittu enimmäismäärä`,
  zY = `Kuinka monta tämän tyyppistä virtuaalista esinettä voi ostaa kerralla. Määritä nolla tai yksi poistaaksesi pudotusvalikon.`,
  BY = `Näytä sovelluksen esinekauppa`,
