  UY = `Lunasta ilmaisesine`,
  WY = `Ilmaisesineille tarkoitettu osio, joka ilmoittaa, milloin pelaaja voi lunastaa seuraavan esineen (jos tarjolla). Voidaan käyttää päivittäisiin esinelöytöihin. Sidottu palkintowidgettiin alennusesineiden määritystä varten.`,
